<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Review;
use App\Domain\Review\Entity\UserFlashcardProgress;use App\Domain\Review\Repository\UserFlashcardProgressRepositoryInterface;use App\Domain\Review\ValueObject\FlashcardProgressState;use App\Infrastructure\Persistence\Doctrine\Review\Entity\FlashcardProgressRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineUserFlashcardProgressRepository implements UserFlashcardProgressRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function find(string $u,string $c):?UserFlashcardProgress{$r=$this->em->find(FlashcardProgressRecord::class,['userId'=>$u,'flashcardId'=>$c]);return $r instanceof FlashcardProgressRecord?$this->map($r):null;} public function save(UserFlashcardProgress $p):void{$r=$this->em->find(FlashcardProgressRecord::class,['userId'=>$p->userId,'flashcardId'=>$p->flashcardId])??new FlashcardProgressRecord();$s=$p->state();$r->userId=$p->userId;$r->flashcardId=$p->flashcardId;$r->dueAt=$s->dueAt;$r->intervalDays=$s->intervalDays;$r->easeFactor=(string)$s->easeFactor;$r->repetitions=$s->repetitions;$r->lapses=$s->lapses;$r->lastReviewedAt=$p->lastReviewedAt;$r->createdAt=$p->createdAt;$r->updatedAt=$p->updatedAt;$this->em->persist($r);} public function dueForUser(string $u,\DateTimeImmutable $now,int $limit):array{$items=$this->em->createQueryBuilder()->select('p')->from(FlashcardProgressRecord::class,'p')->where('p.userId=:u')->andWhere('p.dueAt<=:n')->setParameter('u',$u)->setParameter('n',$now)->orderBy('p.dueAt','ASC')->setMaxResults($limit)->getQuery()->getResult();return array_map(fn(FlashcardProgressRecord $r)=>$this->map($r),$items);} private function map(FlashcardProgressRecord $r):UserFlashcardProgress{return new UserFlashcardProgress($r->userId,$r->flashcardId,new FlashcardProgressState($r->dueAt,$r->intervalDays,(float)$r->easeFactor,$r->repetitions,$r->lapses),$r->lastReviewedAt,$r->createdAt,$r->updatedAt);} }
